import{d as s,C as t,o as d,c as h,E as i,a3 as o}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"坎为水","description":"坎为水，坎上坎下","frontmatter":{"title":"坎为水","description":"坎为水，坎上坎下","category":"hexagram","aliases":["坎","坎为水"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-29.md","filePath":"yijing/hexagrams/hexagram-29.md","lastUpdated":1787800334000}'),p={name:"yijing/hexagrams/hexagram-29.md"},y=s({...p,setup(m){const e=[{id:"xikan",term:"习坎",pinyin:"xí kǎn",meaning:"重险。「习」是重复、练习——不是一次涉险，而是反复习于险。",context:"卦名与初六爻辞开篇。坎之所以为坎，正在于险上加险。"},{id:"kandan",term:"坎窞",pinyin:"kǎn dàn",meaning:"坎中之坎、深坑。窞是深坑；入于坎窞，是陷进了险的最深处。",context:"初六、六三皆「入于坎窞」。"},{id:"qiuxiaode",term:"求小得",pinyin:"qiú xiǎo dé",meaning:"降低预期，先求小的收获。身处险中，小步快跑胜于一步登天。",context:"九二阳陷阴中，守中尚能小有所得。"},{id:"weichuzhong",term:"未出中",pinyin:"wèi chū zhōng",meaning:"尚未脱离中道，亦指尚未走出险境中央。守中不躁，故有小得。",context:"九二小象。"},{id:"xianqiezhen",term:"险且枕",pinyin:"xiǎn qiě zhěn",meaning:"危险又只能枕伏倚靠。枕：倚伏、贴伏；进退皆是险，只能伏着不动。",context:"六三进退两难之象。"},{id:"zhongwugong",term:"终无功",pinyin:"zhōng wú gōng",meaning:"终究没有功效。妄动于险中，结局是徒劳。",context:"六三小象。"},{id:"zun",term:"樽",pinyin:"zūn",meaning:"酒器。"},{id:"gui",term:"簋",pinyin:"guǐ",meaning:"盛食的器皿，圆口双耳。"},{id:"fou",term:"缶",pinyin:"fǒu",meaning:"瓦器、陶罐，质朴之物。"},{id:"nayuezhiyou",term:"纳约自牖",pinyin:"nà yuē zì yǒu",meaning:"以质朴诚信之言（约），从窗户（牖）递入。正门不通，就寻侧窗迂回而入——以诚相交，不必盛礼。",context:"六四居险中，唯以诚动九五。"},{id:"gangrouji",term:"刚柔际",pinyin:"gāng róu jì",meaning:"刚与柔交接之处。六四与九五刚柔相际，正因质地相近，才以简朴致诚。",context:"六四小象。"},{id:"kanbuying",term:"坎不盈",pinyin:"kǎn bù yíng",meaning:"坎陷尚未满盈。水不盈则流而不积，险不盈则终有平复之时。",context:"九五居中，止跌待平。"},{id:"zhi",term:"祗",pinyin:"zhī",meaning:"只、仅仅；亦有安、小之义。",context:"「祗既平」即险坑只差一点就平。"},{id:"zhongweida",term:"中未大",pinyin:"zhōng wèi dà",meaning:"居中而未至于盛大。无咎已足，未可言大功。",context:"九五小象。"},{id:"huimo",term:"徽纆",pinyin:"huī mò",meaning:"绳索；三股为徽，两股为纆，都是束缚之索。",context:"上六被绳绑缚，失道之凶。"},{id:"zhi4",term:"寘",pinyin:"zhì",meaning:"放置、安置。",context:"「寘于丛棘」即被丢进荆棘之中。"},{id:"congji",term:"丛棘",pinyin:"cóng jí",meaning:"丛生的荆棘。古以棘为牢狱，置犯人于丛棘之中。",context:"上六失道受困之象。"},{id:"shidao",term:"失道",pinyin:"shī dào",meaning:"失去正道、迷失路径。入坎而凶，根源在失道。",context:"上六小象。"}],r=[{position:"初六",type:"yin",text:"习坎，入于坎窞，凶。",xiang:"习坎入坎，失道凶也。",textModern:"初入重险，不知深浅，一头扎进坎中最深的坑——无知之凶。先识险，再处险。",xiangModern:"把习坎当成一次涉险，结果掉进深坑——失道的凶，源于不知险。"},{position:"九二",type:"yang",text:"坎有险，求小得。",xiang:"求小得，未出中也。",textModern:"险中还有险，先把期望降到最低，求得小的收获——小步走，也能出险。",xiangModern:"能求得小得，是因为尚未脱离中道——守中，是险中的立足点。"},{position:"六三",type:"yin",text:"来之坎坎，险且枕，入于坎窞，勿用。",xiang:"来之坎坎，终无功也。",textModern:"来也是坎、去也是坎，危险当头只能枕伏不动——进退两难时，勿用即智慧。",xiangModern:"前后来回都是坎，妄动终究没有功效。"},{position:"六四",type:"yin",text:"樽酒，簋贰，用缶，纳约自牖，终无咎。",xiang:"樽酒簋贰，刚柔际也。",textModern:"一樽酒、两簋食，用最朴素的瓦器，从窗户递进去——礼薄而诚厚，正门不通就走侧窗，终无咎。",xiangModern:"一樽酒两簋食的简朴，恰是刚柔交接处最对味的诚意。"},{position:"九五",type:"yang",text:"坎不盈，祗既平，无咎。",xiang:"坎不盈，中未大也。",textModern:"险坑将平未平，差一点就平了——止跌企稳，无咎即已成。",xiangModern:"坎未盈而未平，是因为居中而未至盛大——无咎即功，不必求大。"},{position:"上六",type:"yin",text:"系用徽纆，寘于丛棘，三岁不得，凶。",xiang:"上六失道，凶三岁也。",textModern:"被绳索捆住、丢进丛生的荆棘，三年不得脱身——失道之凶，是自己织的网。",xiangModern:"上六失道，凶要持续三年——失道的代价，从来不是一时。"}];return(u,n)=>{const a=t("DaoHexagramViewer"),l=t("DaoHexagramYaoCards"),g=t("DaoKeywordCards");return d(),h("div",null,[i(a,{name:"坎为水",fullName:"坎为水",upper:"☵",lower:"☵",guaCi:"习坎，有孚，维心亨，行有尚。",pinyin:["kǎn","wéi","shuǐ"],element:"水",direction:"北",virtue:"陷",insight:"险境中守住内心，方能穿越重重危难。",guaSlug:"29kanweishui",lines:r}),n[0]||(n[0]=o('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>水洊至，习坎。君子以常德行，习教事。</p><p>水接连而至、一浪接一浪，正是重险叠加的习坎之象；君子由此悟到，要以<strong>恒常的德行</strong>，去<strong>反复练习教化之事</strong>。</p><p>「常德行」「习教事」的拆解——<strong>常</strong>是恒常不断，水不舍昼夜地流；<strong>习</strong>是反复练习，水一遍遍冲刷河道。德行要常，教事要习：把德练成习惯，把险过成日常。</p><p>分形结构：</p><ul><li>常德行（恒常之德）→ 微观：日日不断，把修养练成习惯</li><li>习教事（反复之教）→ 宏观：在人群中反复示范，像水一样浸润</li></ul><p>「习坎」的「习」，是整卦的钥匙——险不可免，但可以习以为常。水不怕重险，因为水把「流过」练成了本能。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>习坎，重险也。水流而不盈，行险而不失其信。维心亨，乃以刚中也。行有尚，往有功也。天险不可升也，地险山川丘陵也，王公设险以守其国。险之时用大矣哉。</p><p>逐句释义：</p><ul><li><strong>习坎，重险也</strong> —— 坎上加坎，是险上加险的重复。这是坎卦的本质：不是一次险，而是重险。</li><li><strong>水流而不盈，行险而不失其信</strong> —— 水流入坎穴而不满溢，行进于险而不失信用。险中的水是活的，活水才过得了险。</li><li><strong>维心亨，乃以刚中也</strong> —— 内心所以通达，是因为九二、九五两阳刚健而居中。外险而内刚，是穿越重险的唯一引擎。</li><li><strong>行有尚，往有功也</strong> —— 行动起来就有崇尚、就能建功。行动本身，就是对险的回答。</li><li><strong>天险不可升也，地险山川丘陵也，王公设险以守其国</strong> —— 天险高得不可攀登，地险是山川丘陵的起伏，王公顺应地险设防，用以守护国家。</li><li><strong>险之时用大矣哉</strong> —— 险的时用，大得很。险不只是阻碍，更是历练的场与守护的墙。</li></ul><blockquote><p><strong>重险哲学</strong>：险不是一次性的遭遇，是常态化的环境。把险当敌人，险在磨你；把险当磨刀石，你在用险。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"水",guaSlug:"29kanweishui",glossary:e,items:r}),n[1]||(n[1]=o('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-习坎-入于坎窞-凶" tabindex="-1">初六 · 习坎，入于坎窞，凶 <a class="header-anchor" href="#初六-·-习坎-入于坎窞-凶" aria-label="Permalink to &quot;初六 · 习坎，入于坎窞，凶&quot;">​</a></h3><ul><li>位置：卦之初，阴居阳位，才入险境</li><li><strong>习坎</strong> → 重险；初六以为是一次涉险，其实已入重险</li><li><strong>坎窞</strong> → 坎中之坎、深坑；一头扎进险的最深处</li><li>小象点破：<strong>失道凶也</strong>——凶的根源不在环境，在失道</li></ul><p>初六的凶，凶在「无知」：不知道这是重险，不知道深坑在哪里，一头扎下去。它提醒我们——<strong>先识险，再处险</strong>。看见险，是过险的第一步。</p><blockquote><p>无知之凶：初六不是败在环境，是败在连险都不认识。</p></blockquote><h3 id="九二-·-坎有险-求小得" tabindex="-1">九二 · 坎有险，求小得 <a class="header-anchor" href="#九二-·-坎有险-求小得" aria-label="Permalink to &quot;九二 · 坎有险，求小得&quot;">​</a></h3><ul><li>位置：下卦之中，阳刚居中，却陷于上下两阴之间</li><li><strong>坎有险</strong> → 险中还有险，脱身尚早</li><li><strong>求小得</strong> → 把期望降到最低，先求小的收获</li><li>小象：<strong>未出中</strong>——还没走出险境中央，但守中未失</li></ul><p>九二是全卦第一处亮色：身处重险，不妄想一步登天，只求小得。<strong>降低预期、积小胜为大胜</strong>，是险境中最务实的活法。</p><blockquote><p>求小得不是认输，是把目标切成能走完的一步步。</p></blockquote><h3 id="六三-·-来之坎坎-险且枕-勿用" tabindex="-1">六三 · 来之坎坎，险且枕，勿用 <a class="header-anchor" href="#六三-·-来之坎坎-险且枕-勿用" aria-label="Permalink to &quot;六三 · 来之坎坎，险且枕，勿用&quot;">​</a></h3><ul><li>位置：下卦之顶，阴居阳位，进退皆险</li><li><strong>来之坎坎</strong> → 来也是坎，去也是坎</li><li><strong>险且枕</strong> → 危险当头，只能枕伏不动</li><li><strong>勿用</strong> → 此时不可妄动</li><li>小象：<strong>终无功</strong>——进退两难时硬闯，注定徒劳</li></ul><p>六三教的是险中最难的一课：<strong>知止</strong>。前路后路都是险时，最大的智慧不是冲，是蛰伏。蛰伏不是放弃，是等水位。</p><blockquote><p>险中无处可去时，不动就是最好的动。</p></blockquote><h3 id="六四-·-樽酒-簋贰-用缶-纳约自牖-终无咎" tabindex="-1">六四 · 樽酒，簋贰，用缶，纳约自牖，终无咎 <a class="header-anchor" href="#六四-·-樽酒-簋贰-用缶-纳约自牖-终无咎" aria-label="Permalink to &quot;六四 · 樽酒，簋贰，用缶，纳约自牖，终无咎&quot;">​</a></h3><ul><li>位置：上卦之初，阴居阴位，与九五刚柔相际</li><li><strong>樽酒簋贰，用缶</strong> → 一樽酒、两簋食，用最朴素的瓦器</li><li><strong>纳约自牖</strong> → 从窗户递进去，不走正门</li><li>小象：<strong>刚柔际</strong>——正在刚柔交接处，简朴反而最对味</li></ul><p>六四是全卦的转机：从「入坎」到「出坎」的连接点。正门不通，就<strong>以诚迂回、寻窗而入</strong>——礼可以薄，诚不能薄；走不通大路，就走侧门。</p><blockquote><p>纳约自牖：真正的通，不靠排场，靠诚意与迂回。</p></blockquote><h3 id="九五-·-坎不盈-祗既平-无咎" tabindex="-1">九五 · 坎不盈，祗既平，无咎 <a class="header-anchor" href="#九五-·-坎不盈-祗既平-无咎" aria-label="Permalink to &quot;九五 · 坎不盈，祗既平，无咎&quot;">​</a></h3><ul><li>位置：君位，阳刚中正，仍在坎中</li><li><strong>坎不盈</strong> → 险坑尚未满盈</li><li><strong>祗既平</strong> → 差一点就平了</li><li>小象：<strong>中未大</strong>——居中而未至盛大</li><li>意义：止跌企稳，<strong>无咎即成</strong></li></ul><p>九五告诉我们，出险的最后一段往往不是「跃出」，是「稳住」。险将平而未平，能守住不折腾，无咎就是这一爻的成。</p><blockquote><p>出险的最后一步，往往不是跨出去，是稳住。</p></blockquote><h3 id="上六-·-系用徽纆-寘于丛棘-三岁不得-凶" tabindex="-1">上六 · 系用徽纆，寘于丛棘，三岁不得，凶 <a class="header-anchor" href="#上六-·-系用徽纆-寘于丛棘-三岁不得-凶" aria-label="Permalink to &quot;上六 · 系用徽纆，寘于丛棘，三岁不得，凶&quot;">​</a></h3><ul><li>位置：卦之极，阴居极位，物极必反</li><li><strong>徽纆</strong> → 绳索；三股为徽，两股为纆</li><li><strong>丛棘</strong> → 丛生的荆棘，古以棘为狱</li><li><strong>三岁不得</strong> → 三年不得脱身</li><li>小象：<strong>上六失道，凶三岁也</strong>——凶的根源，是失道</li></ul><p>上六是整卦的警示：不是环境把上六捆进荆棘，是<strong>自己丢了道</strong>，把自己送进荆棘。历史对照：司马懿的隐忍是「有孚维心」的正面教材——在曹魏的重重险境中蛰伏、求小得、以诚迂回，终于穿越险境；而司马炎晚年失道，国势如入丛棘。过险靠的不是权谋的锋利，是内心的孚。</p><blockquote><p>上六警示：能过坎的人靠有孚；过不了坎的人，是把道丢在半路的人。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',26)),i(g,{title:"字词释义",items:[{term:"坎",pinyin:["kǎn"],meaning:"陷、险；也指坑洼与水流。坎是「险」的卦象符号。"},{term:"习坎",pinyin:["xí","kǎn"],meaning:"重险。「习」是重复、练习——险上加险，也是练出来的本能。"},{term:"窞",pinyin:["dàn"],meaning:"深坑。「坎窞」即坎中之坎、险的最深处。"},{term:"孚"},{term:"维心",pinyin:["wéi","xīn"],meaning:"维系内心。维，系；心亨则险不困人。"},{term:"枕",pinyin:["zhěn"],meaning:"倚伏、凭靠。「险且枕」：危险而只能伏着。"},{term:"樽",pinyin:["zūn"],meaning:"酒器。"},{term:"簋",pinyin:["guǐ"],meaning:"食器，圆口双耳。"},{term:"缶",pinyin:["fǒu"],meaning:"瓦器、陶罐，质朴之物。"},{term:"纳约自牖",pinyin:["nà","yuē","zì","yǒu"],meaning:"约，简朴、俭约；牖，窗户。以简朴之诚从窗递入，喻迂回传递诚意。"},{term:"祗",pinyin:["zhī"],meaning:"只、仅仅；亦有安、小之义。"},{term:"徽纆",pinyin:["huī","mò"],meaning:"绳索。三股为徽，两股为纆。"},{term:"寘",pinyin:["zhì"],meaning:"放置、安置。"},{term:"丛棘",pinyin:["cóng","jí"],meaning:"丛生的荆棘，古代监狱。"},{term:"洊",pinyin:["jiàn"],meaning:"再次、接连。「水洊至」：水接连而至。"},{term:"常德行",pinyin:["cháng","dé","xíng"],meaning:"恒常的德行。水不舍昼夜，德要不间断。"},{term:"习教事",pinyin:["xí","jiào","shì"],meaning:"反复练习教化之事。"}]}),n[2]||(n[2]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>坎卦讲的是<strong>险境中如何穿越重险</strong>。上坎下坎，险上加险，正是「重险」之象——坎是六十四卦中唯一以「险」命名的重卦。</p><p>卦辞「习坎，有孚，维心亨，行有尚」点明：险不可免，但内心有诚信（有孚）、内心通达（维心亨），行动起来就有收获（行有尚）。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>坎卦把「险」讲透了三层：</p><ul><li><strong>险是常态</strong>（习坎，重险）——险不是偶然，是环境的底色</li><li><strong>险可以穿越</strong>（水流而不盈，行险而不失其信）——活水过险，靠的是不失其信</li><li><strong>险也是守护</strong>（王公设险以守其国）——险不只是阻碍，还是保护</li></ul><p>核心是<strong>有孚维心</strong>：外在的险不可控，内心的孚可控。穿越重险，靠的不是更大的力量，是更真的内心。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>先识险：不把险当意外，把险当常态，先摸清地形</li><li>再降预期：险中不求大胜，求小得，积小胜为大胜</li><li>进退两难时知止：勿用，蛰伏本身就是处险</li><li>以诚迂回：正门不通走窗户，礼可以薄，诚不能薄</li><li>守住有孚维心：险不可怕，失道才可怕</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六爻总览：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>处境</th><th>功课</th></tr></thead><tbody><tr><td>卦辞</td><td>习坎，有孚，维心亨，行有尚</td><td>重险当前</td><td>守心诚信，行动即功</td></tr><tr><td>初六</td><td>习坎，入于坎窞，凶</td><td>无知入险</td><td>先识险，再处险</td></tr><tr><td>九二</td><td>坎有险，求小得</td><td>险中守中</td><td>降低预期，积小胜</td></tr><tr><td>六三</td><td>来之坎坎，险且枕，勿用</td><td>进退两难</td><td>知止蛰伏</td></tr><tr><td>六四</td><td>樽酒簋贰，用缶，纳约自牖</td><td>刚柔交接</td><td>以诚迂回，寻窗而入</td></tr><tr><td>九五</td><td>坎不盈，祗既平，无咎</td><td>止跌企稳</td><td>稳住，无咎即成</td></tr><tr><td>上六</td><td>系用徽纆，寘于丛棘</td><td>失道受缚</td><td>失道之凶，自缚之绳</td></tr></tbody></table><p>三个层次：</p><ul><li><strong>认识险</strong>：初六、九二——先看见险，再学会在险中走</li><li><strong>处险</strong>：六三、六四、九五——知止、以诚、稳住</li><li><strong>警示</strong>：上六——失道，是把险过成狱的入口</li></ul><p>核心洞见：</p><ol><li><strong>重险哲学</strong>——险不是一次性的遭遇，是常态化的环境</li><li><strong>有孚维心</strong>——外在的险不可控，内心的孚可控</li><li><strong>水流而不盈</strong>——险中的水是活的，活水才过得了险</li><li><strong>求小得</strong>——险中最大的智慧，是把目标切成小步</li><li><strong>纳约自牖</strong>——真正的通，靠诚意与迂回，不靠排场</li><li><strong>无咎即成</strong>——出险不是跃出，是稳住</li><li><strong>失道之凶</strong>——能过坎的人靠有孚，过不了坎的人失道</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>坎卦像一本「过险手册」，六个爻串成一条完整的险中之路：</p><ul><li><strong>初六</strong> → 认知层：不知险，是最大的凶</li><li><strong>九二</strong> → 方法论：险中守中，求小得</li><li><strong>六三</strong> → 处境课：进退两难，知止蛰伏</li><li><strong>六四</strong> → 转机点：以诚迂回，寻窗而入</li><li><strong>九五</strong> → 临界态：止跌企稳，无咎即成</li><li><strong>上六</strong> → 警示钟：失道，把自己捆进荆棘</li></ul><p>三个层次：<strong>认识险 → 处险 → 警示</strong>。</p><p>历史对照——司马家族的兴衰，正是坎卦的活教材：司马懿的隐忍，是「有孚维心」的正面示范，在曹魏的重重险境中藏起锋芒、求小得、以诚迂回，最终等来转折；而司马炎晚年失道失德，坐拥天下却把国势拖入「丛棘」。同样的险境，有人穿越，有人受缚——差别的从来不是险，是心里有没有孚。</p><p><strong>一句话收整卦</strong>：坎卦教人<strong>守心过险</strong>——险不可免，但失道与不失道，决定你是穿越险境，还是困在丛棘。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：离（第三十卦）、困（第四十七卦）</li><li>坎与离的连结：坎离相对——水与火、险与明、北与南。坎是至险，离是至明；险中守心，方能见明。坎上离下即为水火既济（第六十三卦）。</li><li>坎与困的连结：坎是重险，困是穷困。坎重在「险」，困重在「穷」；坎教守心过险，困教穷而不坠。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',25))])}}});export{x as __pageData,y as default};
